@Transactional
public void check() {
    Student a = entityManager.find(Student.class, 1L);
    Student b = entityManager.find(Student.class, 1L);
    System.out.println(a == b);
}

@Transactional
public void updateStudent(Student studentReq, Long id) {
    Student student1 = studentRepository.findById(id);   // entityManager.find
    if (student1 == null) {
        throw new RuntimeException("Student not found");
    }
    student1.setName(studentReq.getName());
    studentRepository.flush();
    student1.setAge(studentReq.getAge());
    studentRepository.flush();
    student1.setEmail(studentReq.getEmail());
    studentRepository.flush();
}

@Transactional
public void reattach(Student d) {
    Student managed = entityManager.merge(d);
    d.setName("Changed");
    managed.setAge(30);
    System.out.println(d == managed);
}

@Transactional
public void rename() {
    Student s = entityManager.find(Student.class, 1L);
    entityManager.detach(s);
    s.setName("Rohan");

    Student again = entityManager.find(Student.class, 1L);
    again.setAge(again.getAge() + 1);
    System.out.println(s == again);
}

public void saveAll(List<Student> students) {
    int counter = 0;
    for (Student student : students) {
        entityManager.persist(student);
        counter++;
        if (counter % 100 == 0) {
            entityManager.flush();
            entityManager.clear();
        }
    }
}
